import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='ESG'
E(C,'M1-Z01','ESG: che cosa significa',[CL("Ambiente, sociale o governance?","Seleziona un tema, poi il pilastro ESG.",["Ambiente (E)","Sociale (S)","Governance (G)"],[
 ["Consumi di energia e quota rinnovabile",0,"È un tema ambientale."],["Tasso di infortuni",1,"Salute e sicurezza sono temi sociali."],["Politica anticorruzione",2,"È governance."],
 ["Rifiuti avviati a recupero",0,"Ambientale."],["Ore di formazione per dipendente",1,"Sociale."],["Composizione dell’organo amministrativo",2,"Governance."],
 ["Prelievi idrici",0,"Ambientale."],["Divario retributivo di genere",1,"Sociale."],["Gestione dei rischi e controlli interni",2,"Governance."]],
 "Nove temi di sostenibilità. Collocali nel pilastro ambientale, sociale o di governance.","Raccomandazione (UE) 2025/1710 · VSME")])
E(C,'M1-Z02','La doppia materialità',[LB("Laboratorio · La doppia materialità di una tintoria","Imposti l’analisi di doppia materialità di una tintoria tessile con 80 dipendenti.",[
  ["Processo","tintura e finissaggio di tessuti, forte uso di acqua calda e coloranti"],["Energia","gas naturale per il vapore; elettricità"],["Acque","depuratore interno e scarico in corpo idrico superficiale"],["Clienti","marchi della moda che chiedono dati su sostanze e impronta di carbonio"],["Territorio","area con periodi di scarsità idrica"]],[
  ("Individua tre impatti rilevanti dell’impresa su persone e ambiente.",7,"Prelievi idrici in un’area a scarsità idrica; scarichi con coloranti e sostanze chimiche nel corpo idrico; emissioni di gas serra dal vapore prodotto con gas naturale. Anche l’esposizione dei lavoratori agli agenti chimici è un impatto rilevante.",["Ho individuato acqua e scarichi","Ho individuato le emissioni","Ho considerato i lavoratori"]),
  ("Individua tre rischi o opportunità finanziari.",7,"Rischio di costi crescenti di gas e carbonio; rischio di limitazioni ai prelievi in periodi di siccità con fermi produttivi; rischio di perdere clienti senza dati su sostanze e impronta di carbonio, e opportunità di contratti con chi offre processi a basso consumo d’acqua.",["Ho individuato rischi energetici e climatici","Ho individuato il rischio idrico","Ho individuato rischi e opportunità commerciali"]),
  ("Quali temi risultano rilevanti e perché?",6,"Acqua, inquinamento e sostanze, cambiamenti climatici e salute e sicurezza: ciascuno è rilevante almeno in una delle due prospettive, e acqua e clima in entrambe. Il risultato va documentato con criteri, soglie e coinvolgimento dei portatori di interesse.",["Ho applicato la regola di almeno una prospettiva","Ho indicato i temi rilevanti in entrambe","Ho previsto la documentazione"])],
 "Nel laboratorio imposti l’analisi di doppia materialità di una tintoria. Individua gli impatti su persone e ambiente, i rischi e le opportunità finanziari e i temi rilevanti, poi confronta ogni risposta con la soluzione di riferimento.","Direttiva (UE) 2022/2464 · ESRS 1")])
E(C,'M1-Z03','Il quadro europeo dopo il pacchetto Omnibus I',[SC("Il cliente che chiede il rendiconto","Un grande cliente tedesco, soggetto alla CSRD, chiede a una PMI fornitrice con 60 dipendenti di compilare un questionario di 250 domande per il proprio rendiconto.",[
 ("La PMI è soggetta alla CSRD?",[["No: dopo l’Omnibus I l’obbligo riguarda imprese con più di 1.000 dipendenti e oltre 450 milioni di fatturato",True,"Corretto."],["Sì, come fornitore di un’impresa obbligata",False,"L’obbligo non si trasferisce al fornitore."],["Sì, se fattura più di 10 milioni",False,"Non è la soglia."]]),
 ("Deve rispondere a tutte le 250 domande?",[["Le richieste delle imprese obbligate alle imprese protette sono limitate al perimetro dello standard VSME",True,"Corretto: è il tetto informativo della catena del valore."],["Sì, per contratto deve rispondere a tutto",False,"La normativa limita le richieste."],["No, può ignorare il questionario",False,"Rispondere nel perimetro VSME è utile e spesso decisivo commercialmente."]]),
 ("Quale strategia conviene alla PMI?",[["Preparare un rendiconto VSME e usarlo per rispondere a tutti i clienti",True,"Corretto: un solo documento, riutilizzabile."],["Rispondere in modo diverso a ogni cliente",False,"Moltiplica il lavoro e le incoerenze."],["Aspettare che lo chieda una legge",False,"Il mercato lo chiede già."]])],
 "Le PMI non sono soggette alla CSRD, ma i clienti chiedono dati: il tetto VSME limita le richieste e un rendiconto VSME permette di rispondere a tutti con un solo documento.","Un grande cliente chiede molti dati. Decidi la strategia della PMI.","Direttiva (UE) 2022/2464 come modificata dall’Omnibus I · Racc. (UE) 2025/1710")])
E(C,'M1-Z04','Lo standard VSME: modulo base e modulo completo',[LB("Laboratorio · Il piano del primo rendiconto VSME","Prepari il piano del primo rendiconto VSME di una PMI meccanica con 45 dipendenti.",[
  ["Richieste ricevute","due clienti chiedono emissioni e infortuni; la banca chiede piano di transizione"],["Dati disponibili","bollette, registro infortuni, MUD, buste paga"],["Risorse","un responsabile qualità e un consulente esterno"]],[
  ("Scegli il modulo e motiva.",5,"Si parte dal modulo base B1-B11, che copre le richieste di emissioni e infortuni; si aggiungono le informative del modulo completo richieste dalla banca, come gli obiettivi e il piano di transizione per il clima, se l’impresa è in grado di sostenerli con dati.",["Ho scelto il modulo base","Ho aggiunto le informative richieste dalla banca","Ho motivato la scelta"]),
  ("Associa ai dati disponibili le informative del modulo base.",7,"Bollette e carburanti → B3 energia ed emissioni; MUD e registri → B7 risorse e rifiuti; registro infortuni → B9 salute e sicurezza; buste paga → B8 forza lavoro e B10 retribuzione e formazione; politiche e sanzioni → B2 e B11. B1 descrive la base di preparazione.",["Ho collegato B3 e B7","Ho collegato B8, B9 e B10","Ho considerato B1, B2 e B11"]),
  ("Prepara un calendario di tre mesi.",6,"Mese 1: perimetro, anno di riferimento, responsabili e raccolta dati. Mese 2: calcoli, controlli di coerenza, testi delle politiche. Mese 3: redazione, revisione interna, approvazione della direzione e invio ai clienti e alla banca.",["Ho previsto raccolta e responsabili","Ho previsto calcoli e controlli","Ho previsto approvazione e diffusione"])],
 "Nel laboratorio pianifichi il primo rendiconto VSME di una PMI meccanica. Scegli il modulo, collega i dati disponibili alle informative e prepara un calendario, poi confronta ogni risposta con la soluzione di riferimento.","Raccomandazione (UE) 2025/1710 · VSME")])
E(C,'M1-Z05','Le informative sociali e di governance del modulo base',[CL("Quale informativa del modulo base?","Seleziona un dato, poi l’informativa VSME in cui va riportato.",["B3 · energia ed emissioni","B7 · risorse e rifiuti","B8 · forza lavoro","B9 · salute e sicurezza","B10 · retribuzione e formazione","B11 · corruzione"],[
 ["MWh di gas naturale consumati",0,"Energia."],["Tonnellate di rifiuti avviati a recupero",1,"Risorse e rifiuti."],["Dipendenti per contratto e genere",2,"Forza lavoro."],
 ["Numero e tasso di infortuni registrabili",3,"Salute e sicurezza."],["Ore medie di formazione",4,"Retribuzione e formazione."],["Condanne per corruzione",5,"Governance."],
 ["Emissioni Scope 2",0,"Emissioni."],["Divario retributivo di genere",4,"Retribuzione."]],
 "Otto dati di una PMI. Indica in quale informativa del modulo base VSME vanno riportati.","Raccomandazione (UE) 2025/1710 · VSME, modulo base")])
E(C,'M1-Z06','Tassonomia e finanza sostenibile: perché le banche chiedono dati',[SC("Il questionario della banca","La banca chiede a una PMI, per un finanziamento di un nuovo capannone, dati sulle emissioni, sul rischio di alluvione del sito e sulla classe energetica dell’edificio.",[
 ("Perché la banca chiede questi dati?",[["Per valutare rischi climatici e ambientali secondo gli orientamenti di vigilanza e, se previsto, l’allineamento alla Tassonomia",True,"Corretto."],["Per curiosità",False,"È un obbligo della banca nella gestione del rischio."],["Per pubblicità",False,"Non è lo scopo."]]),
 ("Come risponde la PMI sul rischio di alluvione?",[["Con le mappe di pericolosità ufficiali e le misure di adattamento previste",True,"Corretto: dati verificabili e misure concrete."],["Dichiarando «nessun rischio»",False,"Va dimostrato."],["Non risponde",False,"Riduce le possibilità di ottenere condizioni migliori."]]),
 ("Che cosa può migliorare le condizioni del finanziamento?",[["Un progetto ad alta efficienza energetica documentato e dati ESG coerenti",True,"Corretto: molte banche premiano i progetti sostenibili."],["Un logo verde sul capannone",False,"Non è un dato."],["Promettere di essere carbon neutral",False,"Senza piano e dati è un’asserzione non dimostrabile."]])],
 "Le banche chiedono dati per gestire i rischi climatici e ambientali: dati verificabili e progetti documentati migliorano accesso e condizioni del credito.","Una banca chiede dati ESG per un finanziamento. Prepara la risposta.","Reg. (UE) 2020/852 · orientamenti EBA sui rischi ESG")])
E(C,'M1-Z07','CBAM: il meccanismo di adeguamento del carbonio alle frontiere',[LB("Laboratorio · Il CBAM per un importatore di bulloneria","Un’impresa importa da Paesi terzi prodotti in ferro e acciaio e semilavorati in alluminio.",[
  ["Importazioni previste","viti e bulloni in acciaio 38 t; profilati in alluminio 20 t; utensili non soggetti al CBAM 15 t"],["Situazione","nessuna autorizzazione come dichiarante CBAM"],["Fornitori","nessun dato sulle emissioni incorporate"]],[
  ("L’impresa supera la soglia de minimis?",5,"La soglia di 50 t l’anno si calcola sulla massa complessiva delle merci CBAM di ferro e acciaio, alluminio, fertilizzanti e cemento: 38 + 20 = 58 t, oltre la soglia. Gli utensili non soggetti non si contano.",["Ho sommato solo le merci CBAM","Ho ottenuto 58 t","Ho concluso che la soglia è superata"]),
  ("Quali obblighi ne derivano?",6,"Serve l’autorizzazione come dichiarante CBAM prima di importare oltre soglia; dichiarazione annuale delle quantità e delle emissioni incorporate; acquisto e restituzione dei certificati CBAM, dal 1° febbraio 2027 per le importazioni del 2026.",["Ho indicato l’autorizzazione","Ho indicato la dichiarazione annuale","Ho indicato i certificati"]),
  ("Che cosa chiedi ai fornitori e perché?",6,"I dati sulle emissioni incorporate effettive per installazione, verificati dove richiesto; senza dati si applicano valori predefiniti, di norma più sfavorevoli. Conviene inserire nei contratti l’obbligo di fornire i dati.",["Ho chiesto le emissioni effettive","Ho spiegato i valori predefiniti","Ho proposto clausole contrattuali"])],
 "Nel laboratorio applichi il CBAM a un importatore di bulloneria e profilati. Verifica la soglia, individua gli obblighi e indica che cosa chiedere ai fornitori, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (UE) 2023/956 come modificato dal Reg. (UE) 2025/2083")])
E(C,'M1-Z08','EUDR: prodotti a deforestazione zero',[SC("Il legno degli imballaggi","Una media impresa importa pallet e casse in legno da un Paese extra UE per i propri imballaggi e acquista mobili in legno da un grossista italiano.",[
 ("Il legno importato rientra nell’EUDR?",[["Sì: il legno e diversi prodotti derivati sono materie prime soggette",True,"Corretto: va verificato il codice del prodotto negli allegati."],["No, solo il cacao e il caffè",False,"Il legno è tra le materie prime."],["Solo se certificato",False,"La certificazione non esclude l’obbligo."]]),
 ("Che cosa deve fare l’impresa come operatore?",[["Svolgere la dovuta diligenza e presentare la dichiarazione con la geolocalizzazione degli appezzamenti",True,"Corretto."],["Chiedere solo la fattura al fornitore",False,"Non basta."],["Nulla fino al 2030",False,"Le date di applicazione sono più vicine."]]),
 ("Da quando si applica alle imprese medie?",[["Dal 30 dicembre 2026",True,"Corretto, per operatori grandi e medi."],["Dal 2028",False,"Non è la data."],["Si applica già dal 2023",False,"L’applicazione è stata differita."]])],
 "Il legno è una materia prima EUDR: chi lo immette sul mercato svolge la dovuta diligenza e presenta la dichiarazione con la geolocalizzazione.","Pallet e casse importati. Verifica gli obblighi EUDR.","Reg. (UE) 2023/1115 come modificato")])
E(C,'M1-Z09','Tassonomia UE: ammissibilità e allineamento',[ES("Esempio guidato · Ammissibile o allineata?","Un’impresa installa pompe di calore negli edifici dei clienti.",[
 ["Ammissibilità","L’attività è descritta negli atti delegati della Tassonomia per la mitigazione dei cambiamenti climatici.","Ammissibile"],
 ["Contributo sostanziale","Si verificano i criteri tecnici, ad esempio i requisiti di efficienza e dei refrigeranti.","Criteri tecnici rispettati?"],
 ["Nessun danno significativo","Si verifica il rispetto dei criteri DNSH sugli altri obiettivi, come l’economia circolare e l’inquinamento.","DNSH"],
 ["Garanzie minime","Rispetto dei diritti umani e del lavoro, anticorruzione, fiscalità, concorrenza.","Garanzie sociali"],
 ["Gli indicatori","Quota di fatturato, spese in conto capitale e spese operative allineate.","% fatturato, CapEx, OpEx"]],
 "Un’attività può essere ammissibile senza essere allineata. Installare pompe di calore è un’attività descritta negli atti delegati: è ammissibile. Per essere allineata deve rispettare i criteri tecnici di contributo sostanziale, non arrecare danni significativi agli altri obiettivi e rispettare le garanzie minime. Il risultato si esprime come quota di fatturato, investimenti e spese operative allineati.","Reg. (UE) 2020/852 · Reg. delegato (UE) 2021/2139")])
E(C,'M1-Z10','Esercitazione · Tre questionari diversi',[LB("Laboratorio · Rispondere al questionario del cliente","Un cliente invia a una PMI un questionario con cinque domande. Prepara le risposte con i dati disponibili.",[
  ["Domanda 1","Avete una politica ambientale?"],["Domanda 2","Emissioni Scope 1 e 2 dell’ultimo anno?"],["Domanda 3","Tasso di infortuni?"],["Domanda 4","Avete obiettivi di riduzione delle emissioni?"],["Domanda 5","Siete certificati ISO 14001?"],["Dati della PMI","politica ambientale approvata nel 2025; Scope 1 174 t CO₂e, Scope 2 location-based 97 t; 3 infortuni su 410.000 ore; nessun obiettivo formalizzato; non certificata"]],[
  ("Scrivi le risposte alle domande 1, 2 e 3 con dati e metodo.",7,"1: sì, politica ambientale approvata dalla direzione nel 2025, disponibile su richiesta. 2: Scope 1 174 t CO₂e e Scope 2 location-based 97 t CO₂e nell’anno di riferimento, calcolati secondo la UNI EN ISO 14064-1 con fattori nazionali dichiarati. 3: 3 infortuni registrabili su 410.000 ore lavorate, pari a circa 7,3 per milione di ore.",["Ho riportato dati e metodo","Ho indicato l’anno di riferimento","Ho calcolato il tasso"]),
  ("Come rispondi onestamente alle domande 4 e 5?",5,"4: non ancora; indicare che l’impresa sta definendo obiettivi e un piano d’azione entro una data precisa. 5: no; indicare eventuali pratiche di gestione esistenti, senza dichiarare una certificazione che non c’è.",["Ho evitato affermazioni non vere","Ho indicato i passi in corso"]),
  ("Come renderesti le risposte riutilizzabili per altri clienti?",5,"Raccogliendole in un rendiconto VSME con dati, metodi e fonti, aggiornato ogni anno e approvato dalla direzione, da inviare o allegare ai questionari.",["Ho proposto il rendiconto VSME","Ho previsto l’aggiornamento annuale"])],
 "Nel laboratorio rispondi al questionario ESG di un cliente con i dati disponibili. Scrivi risposte complete di dati e metodo, rispondi con trasparenza dove i dati mancano e rendi le risposte riutilizzabili, poi confronta ogni risposta con la soluzione di riferimento.","Raccomandazione (UE) 2025/1710 · UNI EN ISO 14064-1"),
 AP("Le richieste ESG che ricevi","Fai il punto sulle richieste di dati ESG alla tua organizzazione.",["Questionari dei clienti","Richieste della banca","Piattaforme di valutazione dei fornitori","Bandi e finanziamenti pubblici","Richieste di investitori"],"Il dato richiesto più spesso e chi lo produce","Es.: emissioni Scope 1 e 2, prodotte dall’ufficio tecnico",
  "Fai il punto sulle richieste di dati ESG che ricevi e indica il dato richiesto più spesso.",2),
 VF("Ripasso · Quadro europeo",[["Dopo l’Omnibus I la CSRD riguarda le imprese con più di 1.000 dipendenti e oltre 450 milioni di fatturato.",True,"Vero."],["Un’attività ammissibile alla Tassonomia è sempre allineata.",False,"Falso: l’allineamento richiede criteri tecnici, DNSH e garanzie minime."],["La soglia CBAM di 50 t si calcola sulla massa delle merci soggette.",True,"Vero."],["Una PMI fornitrice di un’impresa obbligata diventa soggetta alla CSRD.",False,"Falso."]],"Ripasso: quattro affermazioni sul quadro europeo.","Omnibus I · Reg. (UE) 2020/852 · CBAM")])
E(C,'M1-Z11','ESG: che cosa significa',[LB("Laboratorio · La politica di sostenibilità","Scrivi la bozza della politica di sostenibilità di una PMI alimentare con 70 dipendenti.",[
  ["Temi rilevanti","energia e clima, rifiuti alimentari e imballaggi, salute e sicurezza, benessere dei lavoratori, qualità e filiera"],["Impegni già presi","raccolta differenziata, fotovoltaico da 200 kW"],["Vincolo","massimo una pagina"]],[
  ("Scrivi gli impegni ambientali della politica.",7,"Ridurre consumi energetici ed emissioni con un piano di efficienza e l’aumento delle rinnovabili; ridurre gli sprechi alimentari e gli imballaggi, privilegiando materiali riciclabili; rispettare gli obblighi ambientali e prevenire l’inquinamento; misurare e rendicontare ogni anno i risultati.",["Ho incluso clima ed energia","Ho incluso sprechi e imballaggi","Ho previsto misura e rendicontazione"],None,120),
  ("Scrivi gli impegni sociali e di governance.",6,"Salute e sicurezza come priorità, con partecipazione dei lavoratori; formazione e pari opportunità; fornitori selezionati anche su criteri ambientali e sociali; comportamento etico e contrasto alla corruzione; canali di segnalazione tutelati.",["Ho incluso salute, sicurezza e persone","Ho incluso la filiera","Ho incluso etica e segnalazioni"],None,100),
  ("Come rendi la politica credibile e non generica?",5,"Approvazione e firma della direzione; obiettivi misurabili con scadenze nel piano d’azione collegato; responsabilità assegnate; comunicazione a dipendenti e clienti; riesame annuale; niente asserzioni come «impatto zero» senza prove.",["Ho collegato obiettivi misurabili","Ho previsto riesame e responsabilità","Ho evitato asserzioni generiche"])],
 "Nel laboratorio scrivi la bozza della politica di sostenibilità di una PMI alimentare. Formula gli impegni ambientali, sociali e di governance e rendi la politica credibile, poi confronta ogni risposta con la soluzione di riferimento.","Raccomandazione (UE) 2025/1710 · Direttiva (UE) 2024/825")])
# ── M2 ──
E(C,'M2-Z01','Raccolta dei dati ambientali',[LB("Laboratorio · La mappa dei dati","Costruisci la mappa dei dati ambientali di una PMI per il rendiconto VSME.",[
  ["Fonti disponibili","fatture di gas ed elettricità; schede carburante della flotta; registro di carico e scarico dei rifiuti; letture del contatore dell’acquedotto; registro delle apparecchiature con gas fluorurati"],["Persone","amministrazione, ufficio tecnico, responsabile ambiente"]],[
  ("Per ogni dato indica fonte, unità di misura e responsabile.",8,"Gas: fatture, Sm³ convertiti in MWh, amministrazione. Elettricità: fatture e contatori, MWh, amministrazione. Carburanti: schede carburante, litri, ufficio acquisti o flotta. Rifiuti: registro e formulari, tonnellate per pericolosi e non pericolosi e per destinazione, responsabile ambiente. Acqua: letture, m³, ufficio tecnico. Gas fluorurati: registro, kg ricaricati, responsabile ambiente.",["Ho indicato le fonti","Ho indicato le unità","Ho assegnato i responsabili"],None,150),
  ("Quali controlli di qualità prevedi?",5,"Confronto con l’anno precedente e spiegazione degli scostamenti; quadratura tra fatture e contatori; coerenza tra registro dei rifiuti e MUD; conservazione delle evidenze; indicazione delle stime.",["Ho previsto confronti e quadrature","Ho previsto la coerenza con il MUD","Ho previsto la tracciabilità"]),
  ("Che cosa fai se manca un dato, ad esempio due mesi di acqua?",5,"Si stima con un metodo dichiarato, ad esempio la media dei mesi disponibili rapportata alla produzione, si indica che è una stima e si corregge il processo di raccolta per l’anno successivo.",["Ho previsto una stima dichiarata","Ho indicato il metodo","Ho previsto il miglioramento"])],
 "Nel laboratorio costruisci la mappa dei dati ambientali di una PMI. Indica fonti, unità e responsabili, i controlli di qualità e come trattare un dato mancante, poi confronta ogni risposta con la soluzione di riferimento.","Raccomandazione (UE) 2025/1710 · UNI EN ISO 14064-1")])
E(C,'M2-Z02','I fattori di emissione per l’energia elettrica',[ES("Esempio guidato · Scope 2 location-based e market-based","Un’impresa consuma 800 MWh di elettricità; 300 MWh sono coperti da garanzie di origine rinnovabili.",[
 ["Location-based","800 MWh × 199,6 g CO₂/kWh, fattore nazionale 2025 in stima preliminare.","≈ 159,7 t CO₂"],
 ["Market-based: quota coperta","300 MWh con garanzie di origine rinnovabili: emissioni nulle.","0 t"],
 ["Market-based: quota residua","500 MWh × residual mix 420,2 g CO₂/kWh.","≈ 210,1 t CO₂"],
 ["Il confronto","Il market-based supera il location-based perché il residual mix è più alto del mix medio.","210,1 > 159,7"],
 ["La comunicazione","Si riportano entrambi i valori, indicando fattori e anno.","Doppio valore dichiarato"]],
 "Calcoliamo lo Scope due. Con il metodo location-based ottocento megawattora per centonovantanove virgola sei grammi per chilowattora danno circa centosessanta tonnellate. Con il metodo market-based, i trecento megawattora coperti da garanzie di origine valgono zero, mentre i cinquecento restanti, con il residual mix di quattrocentoventi grammi, danno circa duecentodieci tonnellate. Si riportano entrambi i valori con fattori e anno.","ISPRA · AIB residual mix · GHG Protocol Scope 2 Guidance")])
E(C,'M2-Z03','Esempio applicativo: Scope 1 dal gas naturale',[LB("Laboratorio · Scope 1 e Scope 2 di una PMI","Calcola le emissioni del 2024 di una PMI.",[
  ["Gas naturale","60.000 Sm³; fattore per le emissioni 2024: 2,019 t CO₂ ogni 1.000 Sm³"],["Gasolio della flotta","18.000 litri; densità 0,835 kg/l; 3,150 t CO₂ per t"],["Gas refrigerante","ricarica di 3 kg di R-410A; GWP AR5 1.924"],["Elettricità","500 MWh; fattore 2024 di 194,0 g CO₂eq/kWh"]],[
  ("Calcola le emissioni di gas naturale e gasolio.",7,"Gas: 60.000 / 1.000 × 2,019 = 121,1 t CO₂. Gasolio: 18.000 × 0,835 = 15.030 kg = 15,03 t; × 3,150 = 47,3 t CO₂.",["Ho calcolato 121,1 t","Ho convertito litri in tonnellate","Ho calcolato 47,3 t"]),
  ("Calcola le emissioni del refrigerante e lo Scope 1 totale.",5,"3 kg × 1.924 = 5.772 kg = 5,8 t CO₂e. Scope 1 = 121,1 + 47,3 + 5,8 ≈ 174,2 t CO₂e.",["Ho usato la ricarica come stima della perdita","Ho calcolato 5,8 t CO₂e","Ho sommato circa 174 t"]),
  ("Calcola lo Scope 2 location-based e indica che cosa dichiari nel rendiconto.",6,"500 MWh × 194,0 g/kWh = 97,0 t CO₂e. Nel rendiconto: Scope 1 174 t e Scope 2 location-based 97 t, con anno, fattori, fonti, serie di GWP e metodo; se disponibile anche il market-based.",["Ho calcolato 97 t","Ho dichiarato fattori, fonti e GWP","Ho considerato il market-based"])],
 "Nel laboratorio calcoli le emissioni Scope uno e Scope due di una PMI per il duemilaventiquattro, da gas naturale, gasolio, refrigerante ed elettricità. Esegui i calcoli e indica che cosa dichiarare, poi confronta ogni risposta con la soluzione di riferimento.","Tabella ISPRA dei parametri standard nazionali · ISPRA fattori elettrici · IPCC AR5")])
E(C,'M2-Z04','Il potenziale di riscaldamento globale (GWP)',[ES("Esempio guidato · Dalle tonnellate di gas alle tonnellate di CO₂e","Le emissioni di un allevamento e di un impianto frigorifero.",[
 ["Metano","2,0 t di CH₄ con GWP AR5 pari a 28.","2,0 × 28 = 56 t CO₂e"],
 ["Protossido di azoto","0,15 t di N₂O con GWP AR5 pari a 265.","0,15 × 265 ≈ 39,8 t CO₂e"],
 ["Refrigerante","Perdita di 10 kg di HFC-134a con GWP AR5 pari a 1.300.","0,010 × 1.300 = 13 t CO₂e"],
 ["Il totale","56 + 39,8 + 13.","≈ 108,8 t CO₂e"],
 ["La coerenza","Con la serie AR6 i valori cambierebbero: si dichiara la serie usata e la si mantiene nel tempo.","Serie dichiarata e costante"]],
 "Convertiamo i gas serra in CO₂ equivalente. Due tonnellate di metano per ventotto fanno cinquantasei tonnellate. Zero virgola quindici tonnellate di protossido di azoto per duecentosessantacinque fanno circa quaranta. Dieci chili di HFC centotrentaquattro a, con GWP milletrecento, fanno tredici tonnellate. In totale circa centonove tonnellate di CO₂ equivalente, con la serie AR cinque dichiarata e mantenuta nel tempo.","IPCC AR5 · UNI EN ISO 14064-1")])
E(C,'M2-Z05','Confini organizzativi e anno base',[SC("Il nuovo stabilimento acquisito","Una PMI con anno base 2023 e 900 t CO₂e acquista nel 2026 un’azienda con uno stabilimento che emette 400 t CO₂e l’anno.",[
 ("Che cosa succede all’anno base?",[["Va ricalcolato includendo lo stabilimento acquisito, se il cambiamento supera la soglia di significatività stabilita",True,"Corretto: confronti coerenti richiedono lo stesso perimetro."],["Resta invariato",False,"Il confronto sarebbe falsato."],["Si cambia anno base ogni anno",False,"Si ricalcola, non si cambia."]]),
 ("Con quale approccio si includono le emissioni?",[["Con l’approccio di consolidamento già scelto, ad esempio il controllo operativo, applicato in modo coerente",True,"Corretto."],["Con un approccio diverso per la nuova società",False,"L’approccio deve essere coerente."],["Solo se conviene",False,"Le regole vanno applicate sempre."]]),
 ("Come comunichi il cambiamento?",[["Spiegando il ricalcolo, i valori prima e dopo e la crescita dovuta all’acquisizione",True,"Corretto: trasparenza sul perimetro."],["Non lo comunichi",False,"Sarebbe fuorviante."],["Dichiari una riduzione",False,"Le emissioni crescono per il perimetro."]])],
 "Acquisizioni e cessioni cambiano il perimetro: l’anno base si ricalcola secondo la soglia stabilita e si comunica con trasparenza.","Un’acquisizione cambia il perimetro dell’inventario. Decidi come gestire l’anno base.","UNI EN ISO 14064-1 · GHG Protocol Corporate Standard")])
E(C,'M2-Z06','Esempio applicativo: il tasso di infortuni del rendiconto',[LB("Laboratorio · Gli indicatori sociali","Calcola gli indicatori sociali del rendiconto di una PMI con 205 dipendenti.",[
  ["Infortuni registrabili","3, nessun decesso"],["Ore lavorate","410.000"],["Giornate perse","95"],["Ore di formazione","2.460"],["Retribuzione oraria media","uomini 16,00 €; donne 14,40 €"]],[
  ("Calcola il tasso di infortuni e le giornate perse per 1.000 ore.",6,"Tasso per milione di ore: 3 / 410.000 × 1.000.000 ≈ 7,3. Giornate perse per 1.000 ore: 95 / 410.000 × 1.000 ≈ 0,23. Si dichiara la base di calcolo usata.",["Ho calcolato circa 7,3","Ho calcolato circa 0,23","Ho dichiarato la base"]),
  ("Calcola le ore medie di formazione e il divario retributivo di genere.",6,"Formazione: 2.460 / 205 = 12 ore per dipendente. Divario: (16,00 − 14,40) / 16,00 = 10%.",["Ho calcolato 12 ore","Ho calcolato il 10%","Ho usato la retribuzione maschile come base"]),
  ("Come commenteresti questi dati nel rendiconto?",5,"Presentando i valori con l’anno precedente, spiegando le cause degli infortuni e le misure adottate, e indicando un obiettivo per il divario retributivo con le azioni previste, ad esempio la revisione dei livelli e la parità nelle progressioni.",["Ho previsto il confronto con l’anno precedente","Ho collegato misure e obiettivi"])],
 "Nel laboratorio calcoli gli indicatori sociali di una PMI: tasso di infortuni, giornate perse, ore di formazione e divario retributivo. Esegui i calcoli e scrivi come commentarli, poi confronta ogni risposta con la soluzione di riferimento.","Raccomandazione (UE) 2025/1710, B9 e B10")])
E(C,'M2-Z07','Integrazione con i sistemi di gestione',[CL("Da quale sistema arriva il dato?","Seleziona un dato del rendiconto, poi il sistema di gestione che lo produce.",["ISO 14001","ISO 45001","ISO 50001","UNI/PdR 125","Modello 231"],[
 ["Registro delle prescrizioni ambientali",0,"Sistema di gestione ambientale."],["Analisi degli infortuni e dei quasi incidenti",1,"Sistema di gestione della salute e sicurezza."],
 ["Indicatori di prestazione energetica",2,"Sistema di gestione dell’energia."],["Indicatori di parità di genere",3,"Prassi di riferimento sulla parità di genere."],
 ["Flussi informativi verso l’organismo di vigilanza",4,"Modello organizzativo."],["Rifiuti per destinazione",0,"Sistema di gestione ambientale."]],
 "Sei dati del rendiconto di sostenibilità. Individua il sistema di gestione che li produce.","UNI EN ISO 14001 · 45001 · 50001 · UNI/PdR 125:2022 · D.lgs. 231/2001")])
E(C,'M2-Z08','Le asserzioni ambientali: Direttiva (UE) 2024/825',[CL("Asserzione ammessa o vietata?","Seleziona un’asserzione, poi la colonna.",["Ammessa, se dimostrata","Vietata"],[
 ["«Prodotto ecologico», senza ulteriori specifiche",1,"Asserzione generica vietata."],["«Imballaggio realizzato con il 70% di plastica riciclata, certificato»",0,"Specifica e verificabile."],
 ["«Neutrale per il clima» grazie a crediti di compensazione",1,"Vietata se basata sulla compensazione."],["«Riduzione del 25% delle emissioni dello stabilimento rispetto al 2022, verificata»",0,"Specifica e documentata."],
 ["Marchio «Amico della natura» creato dall’impresa senza certificazione",1,"Vietato se non basato su un sistema di certificazione."],["«Consumo d’acqua ridotto del 30% per tonnellata di prodotto rispetto al 2023»",0,"Specifica, misurabile."],
 ["«Green» sull’intera gamma per un solo prodotto migliorato",1,"Vietata: estende all’intero prodotto o impresa ciò che vale per una parte."],["«Energia elettrica da garanzie di origine rinnovabili per il 100% dei consumi 2025»",0,"Specifica e documentabile."]],
 "Otto asserzioni ambientali. Distingui quelle ammesse, se dimostrate, da quelle vietate dalla direttiva sulla transizione verde dei consumatori.","Direttiva (UE) 2024/825 · D.lgs. 30/2026")])
E(C,'M2-Z09','Unità funzionale, confini e regole di categoria',[ES("Esempio guidato · Confrontare due imballaggi","L’importanza dell’unità funzionale.",[
 ["La domanda","Quale bottiglia ha l’impronta di carbonio minore: vetro da 0,75 l o PET da 1,5 l?","Confronto da impostare"],
 ["L’unità funzionale","Si confrontano a parità di funzione: contenere e proteggere 1 litro di bevanda fino al consumo.","1 litro confezionato"],
 ["I confini","Dalla culla alla tomba, includendo trasporti, riutilizzo e fine vita.","Culla-tomba"],
 ["Le regole","Si usano le stesse regole di categoria di prodotto e gli stessi dati di fine vita.","Stesse PCR"],
 ["Il risultato","Solo così il confronto è valido; un confronto per bottiglia sarebbe fuorviante.","Confronto per litro"]],
 "Per confrontare due imballaggi serve un’unità funzionale comune. Una bottiglia di vetro da tre quarti e una di plastica da un litro e mezzo non si confrontano per bottiglia, ma per litro di bevanda contenuto e protetto fino al consumo, dalla culla alla tomba e con le stesse regole di categoria. Solo così il confronto è corretto.","UNI EN ISO 14067 · UNI EN ISO 14044")])
E(C,'M2-Z10','La verifica di parte terza: livelli di garanzia',[SC("La verifica del rendiconto","Un cliente chiede che il rendiconto VSME di una PMI sia verificato da terzi.",[
 ("Quale livello di garanzia chiedi?",[["Di norma una garanzia limitata, adeguata a un primo rendiconto e meno onerosa",True,"Corretto: la garanzia ragionevole richiede più evidenze e costi."],["Sempre la garanzia ragionevole",False,"È più onerosa e non sempre necessaria."],["Nessuna, basta l’autodichiarazione",False,"Il cliente ha chiesto una verifica."]]),
 ("Che cosa prepari per il verificatore?",[["Dati, fonti, fattori di emissione, calcoli e documenti di supporto tracciabili",True,"Corretto: il verificatore campiona dati e calcoli."],["Solo il documento finale",False,"Non è verificabile."],["Una presentazione commerciale",False,"Non serve."]]),
 ("Il verificatore trova un errore rilevante nello Scope 2. Che cosa fai?",[["Correggi il dato e documenti la correzione prima della dichiarazione di verifica",True,"Corretto."],["Chiedi di ignorarlo",False,"Comprometterebbe la verifica."],["Pubblichi senza verifica",False,"Il cliente l’ha chiesta."]])],
 "Garanzia limitata per iniziare, documentazione tracciabile e correzioni trasparenti: la verifica di terza parte aumenta la credibilità dei dati.","Un cliente chiede la verifica del rendiconto. Organizzala.","ISAE 3000 · UNI EN ISO 14064-3")])
E(C,'M2-Z11','Qualità dei dati, comunicazione e greenwashing',[LB("Laboratorio · Obiettivi e piano d’azione","Definisci obiettivi e azioni per la PMI del laboratorio sulle emissioni: Scope 1 174 t, Scope 2 location-based 97 t, anno base 2024.",[
  ["Fonti principali","gas per riscaldamento e processo; gasolio della flotta; elettricità"],["Opportunità","tetto disponibile per fotovoltaico; caldaie vecchie; flotta da rinnovare entro 3 anni"]],[
  ("Formula un obiettivo misurabile di riduzione.",5,"Ridurre le emissioni Scope 1 e 2 del 30% entro il 2030 rispetto al 2024, da 271 a circa 190 t CO₂e, con verifica annuale.",["Ho indicato percentuale e scadenza","Ho indicato l’anno base","Ho calcolato il valore obiettivo"]),
  ("Proponi tre azioni con una stima del contributo.",8,"Fotovoltaico per circa 150 MWh l’anno: circa 29 t con il fattore 194 g/kWh. Pompe di calore o caldaie a condensazione per metà del gas: circa 40-60 t. Rinnovo della flotta con veicoli più efficienti ed eco-guida: circa 10-15 t. Totale indicativo 80-100 t.",["Ho proposto azioni sulle fonti principali","Ho stimato i contributi","Ho verificato che raggiungano l’obiettivo"],None,120),
  ("Come comunichi l’obiettivo senza greenwashing?",5,"Con dati di partenza, obiettivo, perimetro e azioni; riportando i progressi ogni anno; senza dichiarare neutralità climatica basata su compensazioni né usare termini generici come «green».",["Ho indicato dati e perimetro","Ho previsto la rendicontazione dei progressi","Ho evitato asserzioni vietate"])],
 "Nel laboratorio definisci obiettivi e azioni di riduzione delle emissioni per una PMI. Formula un obiettivo misurabile, proponi tre azioni con il loro contributo e indica come comunicarlo senza greenwashing, poi confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 14064-1 · Direttiva (UE) 2024/825")])
E(C,'M2-Z12','Esercitazione · Il rendiconto «impatto zero»',[LB("Laboratorio · Riscrivere le asserzioni","Riscrivi le frasi del sito di una PMI dopo la revisione legale.",[
  ["Frase 1","«Siamo un’azienda green al 100%»"],["Frase 2","«I nostri prodotti sono a impatto zero grazie ai crediti di carbonio»"],["Frase 3","«Usiamo solo energia pulita»"],["Dati disponibili","fotovoltaico che copre il 35% dei consumi elettrici; garanzie di origine per il resto dell’elettricità nel 2025; riduzione del 18% delle emissioni Scope 1 e 2 dal 2022; crediti acquistati per 200 t"]],[
  ("Riscrivi la frase 1.",5,"«Dal 2022 abbiamo ridotto del 18% le emissioni di gas serra dirette e da energia elettrica dei nostri stabilimenti.» Si sostituisce un’asserzione generica con un risultato specifico e verificabile.",["Ho eliminato il termine generico","Ho usato un dato verificabile","Ho indicato perimetro e periodo"]),
  ("Riscrivi la frase 2.",6,"«Nel 2025 abbiamo finanziato progetti di riduzione o assorbimento per 200 t CO₂e, in aggiunta ai nostri obiettivi di riduzione.» Non si dichiara neutralità del prodotto basata sulle compensazioni.",["Ho eliminato «impatto zero»","Ho distinto compensazione e riduzione","Ho indicato quantità e anno"]),
  ("Riscrivi la frase 3.",5,"«Nel 2025 il 35% della nostra elettricità è stato prodotto dal nostro impianto fotovoltaico e il restante 65% è stato coperto da garanzie di origine rinnovabili.» L’asserzione riguarda l’elettricità, non tutta l’energia, che comprende anche il gas.",["Ho limitato l’asserzione all’elettricità","Ho distinto autoproduzione e garanzie","Ho indicato l’anno"])],
 "Nel laboratorio riscrivi tre frasi del sito di una PMI che rischiano di essere asserzioni ambientali vietate. Usa i dati disponibili per trasformarle in affermazioni specifiche e verificabili, poi confronta ogni risposta con la soluzione di riferimento.","Direttiva (UE) 2024/825 · D.lgs. 30/2026"),
 AP("Il tuo primo rendiconto","Scegli le prossime azioni per il rendiconto di sostenibilità della tua organizzazione.",["Nominare un referente","Costruire la mappa dei dati","Calcolare Scope 1 e 2","Calcolare gli indicatori sociali","Scrivere la politica di sostenibilità","Definire obiettivi","Rivedere le asserzioni del sito"],"L’azione numero uno e la data entro cui completarla","Es.: calcolo Scope 1 e 2 del 2025 entro marzo",
  "Scegli le prossime azioni per il rendiconto di sostenibilità della tua organizzazione e indica l’azione numero uno con una data.",3)])

E(C,'M1-Z12','Tassonomia e finanza sostenibile: perché le banche chiedono dati',[LB("Laboratorio · Il rischio climatico fisico del sito","Valuti i rischi climatici fisici di uno stabilimento per il questionario di una banca.",[
  ["Sito","pianura, a 400 m da un fiume, in area a pericolosità idraulica media secondo le mappe ufficiali"],["Attività","lavorazioni con forni; magazzino al piano terra"],["Eventi recenti","allagamento del piazzale nel 2023; estati con temperature interne oltre 35 °C"],["Approvvigionamento idrico","pozzo, con abbassamento della falda in estate"]],[
  ("Individua i pericoli climatici rilevanti per il sito.",6,"Alluvioni e allagamenti da eventi intensi; ondate di calore; siccità e riduzione della disponibilità idrica. Sono pericoli acuti e cronici che possono crescere con i cambiamenti climatici.",["Ho individuato l’alluvione","Ho individuato il calore","Ho individuato la siccità"]),
  ("Valuta esposizione e vulnerabilità.",6,"Esposti: magazzino al piano terra, impianti elettrici e merci; lavoratori nei reparti caldi; processi che usano acqua di pozzo. Vulnerabilità alta per merci e quadri elettrici a quota bassa e per i lavoratori vicino ai forni; media per l’acqua, se esistono alternative.",["Ho considerato beni e persone","Ho graduato la vulnerabilità","Ho considerato i processi"]),
  ("Proponi misure di adattamento da indicare alla banca.",6,"Sopraelevazione di quadri e merci, barriere mobili e piano di emergenza per allagamenti; ventilazione, schermature e organizzazione dei turni nelle ondate di calore; ricircolo e accumulo dell’acqua; copertura assicurativa adeguata. Indicare tempi e costi.",["Ho proposto misure per ogni pericolo","Ho indicato tempi e costi","Ho considerato l’assicurazione"])],
 "Nel laboratorio valuti i rischi climatici fisici di uno stabilimento per una banca. Individua i pericoli, valuta esposizione e vulnerabilità e proponi misure di adattamento, poi confronta ogni risposta con la soluzione di riferimento.","Reg. (UE) 2020/852, Appendice A all’Allegato I del Reg. delegato (UE) 2021/2139")])
E(C,'M1-Z13','La catena del valore e il tetto informativo dello standard VSME',[SC("La piattaforma di rating","Un cliente chiede a una PMI di iscriversi a una piattaforma di valutazione ESG a pagamento, con un questionario molto esteso.",[
 ("Che cosa valuti per prima cosa?",[["Se le informazioni richieste vanno oltre il perimetro VSME e se il cliente accetta il rendiconto VSME",True,"Corretto: il tetto informativo protegge le PMI della catena del valore."],["Ti iscrivi subito",False,"Valuta prima costi e perimetro."],["Rifiuti senza rispondere",False,"Meglio proporre un’alternativa."]]),
 ("Quale alternativa proponi?",[["Inviare il rendiconto VSME, con dati e metodi, e rispondere alle domande che vi rientrano",True,"Corretto."],["Inviare la brochure aziendale",False,"Non contiene dati."],["Promettere dati in futuro",False,"Meglio fornire ciò che c’è con trasparenza."]]),
 ("Se il cliente insiste per la piattaforma?",[["Valuti costi e benefici commerciali e, se aderisci, riutilizzi i dati del rendiconto",True,"Corretto: un solo set di dati per più canali."],["Compili con stime non dichiarate",False,"Le stime vanno dichiarate."],["Copi i dati di un concorrente",False,"È scorretto."]])],
 "Il tetto informativo VSME consente di proporre un rendiconto standard al posto di questionari estesi; se si aderisce a una piattaforma, si riusano gli stessi dati.","Un cliente chiede l’iscrizione a una piattaforma di rating. Decidi.","Omnibus I · Raccomandazione (UE) 2025/1710")])
E(C,'M2-Z13','Le categorie di emissione della UNI EN ISO 14064-1',[LB("Laboratorio · Le emissioni indirette significative","Classifichi le fonti di emissione indirette di un’impresa di arredamento e valuti quali includere.",[
  ["Fonti","acquisto di pannelli e vernici; trasporto dei prodotti ai clienti con vettori esterni; viaggi di lavoro; pendolarismo dei dipendenti; rifiuti avviati a smaltimento; uso dei mobili presso i clienti; fine vita dei mobili"],["Dati","spesa per acquisti; tonnellate-chilometro dei trasporti; questionario sul pendolarismo"]],[
  ("Assegna ogni fonte alla categoria della UNI EN ISO 14064-1.",7,"Categoria 3, trasporti: trasporto dei prodotti, viaggi di lavoro, pendolarismo. Categoria 4, prodotti utilizzati dall’organizzazione: pannelli, vernici, smaltimento dei rifiuti. Categoria 5, uso dei prodotti dell’organizzazione: uso e fine vita dei mobili.",["Ho assegnato i trasporti alla categoria 3","Ho assegnato acquisti e rifiuti alla categoria 4","Ho assegnato uso e fine vita alla categoria 5"]),
  ("Quali criteri usi per decidere se una fonte è significativa?",5,"Entità stimata delle emissioni, influenza dell’impresa sulla fonte, rischi e opportunità, richieste dei portatori di interesse, disponibilità dei dati. I criteri si documentano e le esclusioni si giustificano.",["Ho elencato i criteri","Ho previsto la documentazione delle esclusioni"]),
  ("Quali fonti includeresti nel primo inventario e come le stimeresti?",6,"Acquisti di pannelli e vernici, con fattori per tonnellata o per spesa; trasporto dei prodotti, con tonnellate-chilometro; pendolarismo, con il questionario. Le stime vanno dichiarate e migliorate nel tempo con dati dei fornitori.",["Ho scelto le fonti più rilevanti","Ho indicato i metodi di stima","Ho previsto il miglioramento dei dati"])],
 "Nel laboratorio classifichi le emissioni indirette di un’impresa di arredamento. Assegna le fonti alle categorie, individua i criteri di significatività e scegli che cosa includere nel primo inventario, poi confronta ogni risposta con la soluzione di riferimento.","UNI EN ISO 14064-1:2019")])
